#include <iostream>
#include <string>
using namespace std;

int main() {
    int N, A, B;
    cin >> N >> A >> B;
    string S;
    cin >> S;

    // 先頭から A 文字、末尾から B 文字だけ取り除く
    // → 0-indexed で A 文字目以降、N-B 文字目より前が残る
    int start = A;
    int end = N - B;

    // 取り除かれない文字を順番に出力する
    for (int i = start; i < end; ++i) {
        cout << S[i];
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    int N, A, B;
    cin >> N >> A >> B;
    string S;
    cin >> S;

    // (0-indexed で) A 文字目から、合計 N - A - B 文字取り出す
    cout << S.substr(A, N - A - B) << endl;
    return 0;
}
